DO $curadoria$ BEGIN IF (SELECT count(*) FROM public."ProdutoCatalogo" p WHERE p.id = '27e90c72-fac7-5b1d-b4dc-708ea502d13e'::uuid AND p.nome = 'Cepravin Anti-Mastitico P/ Vaca Sec.' AND p.apresentacao IS NOT DISTINCT FROM 'Seringa 3 g' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Schering-Plough Saúde Animal Ind. e Com. Ltda.' AND p."orientacaoBula" IS NULL) <> 1 THEN RAISE EXCEPTION 'Identidade divergente ou referência já preenchida'; END IF; UPDATE public."ProdutoCatalogo" p SET "orientacaoBula" = '{"versao":3,"fonte":"https://www.msd-saude-animal.com.br/produto/cepravin/","titulo":"Ficha oficial brasileira — Cepravin Anti-Mastitico P/ Vaca Sec.","tipoFonte":"FICHA_OFICIAL","consultadaEm":"2026-11-18","documentoSha256":"e877e0e97e850a88cc033fc953d88241f5d6be42dbf373c27d83b5ed7de806b2","especie":"Bovinos — vacas secas; não usar em lactação.","concentracao":null,"dosagem":"Uma seringa por quarto após a última ordenha da lactação.","proporcoes":[],"via":"Intramamária, pelo canal do teto.","carencias":{"leite":{"estado":"NAO_INFORMADO","horas":null,"condicao":"A fonte autoriza o leite quatro dias após o PARTO somente se houver pelo menos 54 dias entre administração e parto. Não é prazo contado da aplicação; para intervalo menor, não há orientação publicada."},"carne":{"estado":"PRAZO","horas":0,"condicao":"Bovinos: carência zero expressamente declarada."}},"cuidados":"Não usar em vacas em lactação nem em animais hipersensíveis a betalactâmicos. Higienizar o teto antes de infundir. Guardar em local seco, fresco e protegido da luz.","camposFonte":{"dosagem":{"url":"https://www.msd-saude-animal.com.br/produto/cepravin/","secao":"Resumo da bula — dosagem"},"via":{"url":"https://www.msd-saude-animal.com.br/produto/cepravin/","secao":"Resumo da bula — via"},"carenciasCarne":{"url":"https://www.msd-saude-animal.com.br/produto/cepravin/","secao":"Períodos de carência — carne"},"cuidados":{"url":"https://www.msd-sau