DO $curadoria$ BEGIN IF (SELECT count(*) FROM public."ProdutoCatalogo" p WHERE p.id = '0b842944-184a-5219-9a88-0705b842e170'::uuid AND p.nome = 'Chorulon 5000 Ui' AND p.apresentacao IS NOT DISTINCT FROM 'Frasco 5 ml' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Intervet do Brasil Veterinária Ltda.' AND p."orientacaoBula" IS NULL) <> 1 THEN RAISE EXCEPTION 'Identidade divergente ou referência já preenchida'; END IF; UPDATE public."ProdutoCatalogo" p SET "orientacaoBula" = '{"versao":2,"fonte":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","titulo":"Ficha oficial brasileira — Chorulon 5000 Ui","tipoFonte":"FICHA_OFICIAL","consultadaEm":"2026-11-18","documentoSha256":"4f61d4c5af7241179ebcc51206c43ebe126e699c086393726cfd77da16057fa4","documentosComplementares":[{"url":"https://www.msd-saude-animal.com.br/wp-content/uploads/sites/55/2020/07/chorulon-table.png","secao":"Tabela oficial de dosagem e administração","documentoSha256":"2325752caadbb1a6f60c59faac22dedae7770acdfe42cde36f3ce3e24fab7a1c"}],"especie":"Bovinos — vacas e novilhas","concentracao":"5.000 UI de hCG por frasco, acompanhado de 5 mL de diluente.","dosagem":"Vacas e novilhas: para melhora da concepção, 1.500 UI por via IM ou IV na inseminação ou monta; doença cística ovariana, 3.000 UI por via IV. Doses expressas em UI por indicação, sem proporção por kg.","proporcoes":[],"via":"Intramuscular ou intravenosa na indicação de concepção; intravenosa na doença cística ovariana.","carencias":{"leite":{"estado":"PRAZO","horas":0,"condicao":"Bovinos: carência zero declarada."},"carne":{"estado":"PRAZO","horas":0,"condicao":"Bovinos: carência zero declarada."}},"cuidados":"Reconstituir com todo o diluente. Conservar entre 2 e 8 °C, protegido da luz; após reconstituição, manter refrigerado e utilizar em até 12 horas. Podem ocorrer reações anafiláticas.","camposFonte":{"concentracao":{"url":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","secao":"Composição / descrição"},"dosagem":{"url":"https://www.msd-saude-animal.com.br/wp-content/uploads/sites/55/2020/07/chorulon-table.png","secao":"Tabela — bovinos"},"proporcoes":{"url":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","secao":"Dosagem por indicação, sem proporção por peso"},"via":{"url":"https://www.msd-saude-animal.com.br/wp-content/uploads/sites/55/2020/07/chorulon-table.png","secao":"Tabela — bovinos"},"carenciasLeite":{"url":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","secao":"Períodos de carência — leite"},"carenciasCarne":{"url":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","secao":"Períodos de carência — carne"},"cuidados":{"url":"https://www.msd-saude-animal.com.br/produto/chorulon-5000-ui/","secao":"Resumo da bula — cuidados"}}}'::jsonb, "conferenciaBula" = NULL, "atualizadoEm" = CURRENT_TIMESTAMP WHERE p.id = '0b842944-184a-5219-9a88-0705b842e170'::uuid AND p.nome = 'Chorulon 5000 Ui' AND p.apresentacao IS NOT DISTINCT FROM 'Frasco 5 ml' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Intervet do Brasil Veterinária Ltda.' AND p."orientacaoBula" IS NULL; END $curadoria$;
